import { useCallback, useEffect, useRef, useState } from 'react';
import { hasSeenGettingStarted, markGettingStartedSeen } from '../lib/persist';
import {
  VIEWS,
  type View,
  LEGACY_VIEW_MAP,
  PERIOD_VALUES,
  buildRouteHash,
  parseRouteHash,
} from '../lib/viewConfig';

export type CollapsedState = Record<string, boolean>;

/**
 * Single owner of URL-routable state: view, time period, and highlighted
 * route. All three serialize into the address-bar hash (`#routes&route=36`
 * + sticky `period=`), are parsed from it on first load and on Back/forward,
 * and are written back as the user navigates.
 *
 * Precedence on first render: hash > ?view= > 'home'; period/hash come from
 * the hash first, then persisted defaults supplied by the caller.
 */
export function useViewRouting(options: {
  /** Persisted fallbacks for state the hash doesn't carry. */
  savedPeriod: string | null;
  savedHighlightedRoute: string | null;
}) {
  const { savedPeriod, savedHighlightedRoute } = options;

  // One-time parse of the entry URL, before first render.
  const [initial] = useState(() => ({
    hash: parseRouteHash(window.location.hash),
    requested: new URLSearchParams(window.location.search).get('view'),
  }));

  const [view, setView] = useState<View>(() => {
    const fromHash = initial.hash.view;
    if (fromHash && VIEWS.some((v) => v.key === fromHash)) return fromHash as View;
    // Legacy redirect: old key -> new tab (+ optional anchor)
    if (fromHash && LEGACY_VIEW_MAP[fromHash]) {
      const target = LEGACY_VIEW_MAP[fromHash];
      requestAnimationFrame(() => {
        if (target.anchor) document.getElementById(target.anchor)?.scrollIntoView({ behavior: 'smooth', block: 'start' });
      });
      return target.view;
    }
    return VIEWS.some((v) => v.key === initial.requested) ? (initial.requested as View) : 'home';
  });

  const [period, setPeriod] = useState<string>(() => {
    const fromHash = initial.hash.period;
    if (fromHash && PERIOD_VALUES.has(fromHash)) return fromHash;
    return savedPeriod && PERIOD_VALUES.has(savedPeriod) ? savedPeriod : 'all_day';
  });

  const [highlightedRoute, setHighlightedRoute] = useState<string | null>(
    initial.hash.route ?? savedHighlightedRoute,
  );

  // Mirrors `view` for the hashchange listener below, which is registered
  // once and must not re-bind on every navigation.
  const viewRef = useRef(view);
  useEffect(() => {
    viewRef.current = view;
  }, [view]);

  const [showHelp, setShowHelp] = useState(() => !hasSeenGettingStarted());

  const [collapsed, setCollapsed] = useState<CollapsedState>(() => {
    try {
      const raw = localStorage.getItem('miway_sidebar_collapsed');
      return raw ? JSON.parse(raw) : {};
    } catch {
      return {};
    }
  });

  const toggleGroup = useCallback((group: string) => {
    setCollapsed((prev) => {
      const next = { ...prev, [group]: !prev[group] };
      try { localStorage.setItem('miway_sidebar_collapsed', JSON.stringify(next)); } catch {}
      return next;
    });
  }, []);

  const dismissHelp = useCallback(() => {
    setShowHelp(false);
    markGettingStartedSeen();
  }, []);

  // ---- deep-link hash routing (T35) --------------------------------------
  // Write-back: keep the address bar in sync with the routable state so a
  // view is shareable/copyable. Setting `location.hash` pushes a history
  // entry (so browser Back/forward traverse views). `period` is intentionally
  // kept out of the live write-back value — it behaves as sticky global
  // filter state, so it never re-asserts itself over a Back/forward
  // navigation (which would push a phantom history entry and fight Back).
  useEffect(() => {
    const next = buildRouteHash(view, highlightedRoute);
    if (window.location.hash !== next) window.location.hash = next;
  }, [view, highlightedRoute]);

  // Inbound: apply hash navigation (Back/forward, manual edit) to app state.
  useEffect(() => {
    const apply = () => {
      const parsed = parseRouteHash(window.location.hash);
      const known =
        parsed.view &&
        (VIEWS.some((v) => v.key === parsed.view) || !!LEGACY_VIEW_MAP[parsed.view]);
      if (parsed.view && !known) {
        // Unknown view token (#nonsense, typo'd share link): the app ignores
        // it but would otherwise leave the address bar advertising a view it
        // is not showing. Snap back to the current view's canonical hash.
        // location.replace swaps the URL without pushing a history entry.
        window.location.replace(buildRouteHash(viewRef.current, parsed.route ?? null));
        return;
      }
      if (parsed.view && VIEWS.some((v) => v.key === parsed.view)) {
        setView(parsed.view as View);
      } else if (parsed.view && LEGACY_VIEW_MAP[parsed.view]) {
        const target = LEGACY_VIEW_MAP[parsed.view];
        setView(target.view);
        if (target.anchor) {
          requestAnimationFrame(() => {
            document.getElementById(target.anchor!)?.scrollIntoView({ behavior: 'smooth', block: 'start' });
          });
        }
      }
      // Reset the highlight when the nav has no route= (so write-back doesn't
      // re-assert a stale route over a Back to a hash that dropped it).
      setHighlightedRoute(parsed.route ?? null);
      if (parsed.period && PERIOD_VALUES.has(parsed.period)) setPeriod(parsed.period);
    };
    window.addEventListener('hashchange', apply);
    return () => window.removeEventListener('hashchange', apply);
  }, []);

  return {
    view,
    setView,
    period,
    setPeriod,
    highlightedRoute,
    setHighlightedRoute,
    showHelp,
    setShowHelp,
    dismissHelp,
    collapsed,
    toggleGroup,
  };
}
