import { useCallback, useEffect, useRef, useState } from 'react';
import { api } from '../lib/api';
import { LOAD_STEPS, type LoadStepKey } from '../lib/viewConfig';
import type {
  CircuityGeoJSON,
  CircuitySummaryRoute,
  TimePeriod,
  TransferNode,
} from '../types';

/** Memoized per-period payload of the static queries, so revisiting a period
 * re-renders instantly instead of re-fetching / re-parsing everything. */
interface StaticCacheEntry {
  health: string;
  dataFreshness: string | null;
  feedVintage: { start_date: string | null; end_date: string | null; version: string | null } | null;
  circuity: CircuityGeoJSON;
  summary: {
    flagged: CircuitySummaryRoute[];
    threshold: number;
    periods?: Record<string, TimePeriod>;
  };
  nodes: TransferNode[];
  /** True once every phase (including the slow transfer-graph query) settled. */
  complete: boolean;
}

/**
 * Owns the backend's shared static data (feed health, route shapes, circuity
 * summary, transfer nodes) for the selected time period, the per-period
 * cache, the startup load-progress bar, and the load error channel.
 *
 * `period` triggers a reload when it changes; `view` is only read to apply
 * load-progress policy (the 'home' step is completed by HomePanel when it
 * mounts, so it must be marked done immediately when Home is not showing).
 */
export function useStaticData(
  period: string,
  view: string,
  /** Initial transfer nodes (hydrates the persisted optimizer result). */
  initialNodes: TransferNode[] = [],
) {
  // Mirrors `view` for use inside loadStatic, whose identity must stay tied
  // to `period` only (re-running on every view change would refetch).
  const viewRef = useRef(view);
  useEffect(() => {
    viewRef.current = view;
  }, [view]);

  const [health, setHealth] = useState<string | null>(null);
  const [dataFreshness, setDataFreshness] = useState<string | null>(null);
  const [feedVintage, setFeedVintage] = useState<StaticCacheEntry['feedVintage']>(null);
  const [circuity, setCircuity] = useState<CircuityGeoJSON | null>(null);
  const [flaggedRoutes, setFlaggedRoutes] = useState<CircuitySummaryRoute[]>([]);
  const [circuityThreshold, setCircuityThreshold] = useState(1.4);
  const [nodes, setNodes] = useState<TransferNode[]>(initialNodes);
  const [periods, setPeriods] = useState<Record<string, TimePeriod> | null>(null);
  const [error, setError] = useState<string | null>(null);

  const [loadProgress, setLoadProgress] = useState<{
    done: number;
    total: number;
    label: string;
  } | null>(null);

  const staticCacheRef = useRef<Record<string, StaticCacheEntry>>({});
  const loadSeqRef = useRef(0);

  // Steps can complete out of order (HomePanel's fast cached queries often
  // settle before the slow transfer-graph query), so a monotonic counter is
  // wrong: it can hide the bar early and then strand it at 4/5. Track the
  // *set* of completed steps instead; hide only when every step is done.
  const completedStepsRef = useRef(new Set<LoadStepKey>());
  const finishLoadStep = useCallback((key: LoadStepKey) => {
    completedStepsRef.current.add(key);
    const remaining = LOAD_STEPS.filter((s) => !completedStepsRef.current.has(s.key));
    if (remaining.length === 0) {
      setLoadProgress(null);
      return;
    }
    setLoadProgress({
      done: LOAD_STEPS.length - remaining.length,
      total: LOAD_STEPS.length,
      label: remaining[0].label,
    });
  }, []);

  // Stable identity so HomePanel's settle-effect (which depends on onLoaded
  // and calls it) can't re-fire in a loop: an inline arrow would be a new
  // function every render, re-triggering the effect -> setLoadProgress ->
  // re-render -> new arrow -> effect ... ("Maximum update depth exceeded").
  const onHomeLoaded = useCallback(() => finishLoadStep('home'), [finishLoadStep]);

  // HomePanel is the only component that completes the 'home' load step, and
  // it unmounts when the user navigates away — so leaving Home early would
  // leave the startup bar stuck at 80% forever. Complete the step on exit.
  useEffect(() => {
    if (view !== 'home') finishLoadStep('home');
  }, [view, finishLoadStep]);

  const loadStatic = useCallback(async () => {
    completedStepsRef.current = new Set(); // fresh load -> fresh progress
    setLoadProgress({ done: 0, total: LOAD_STEPS.length, label: LOAD_STEPS[0].label });
    const seq = ++loadSeqRef.current;

    // If the user is already on a non-home view, HomePanel never mounts and
    // its onLoaded can't complete the 'home' step — mark it done now so the
    // bar can't strand at 4/5 after a period switch or a Retry.
    if (viewRef.current !== 'home') finishLoadStep('home');

    // Fast path: a previous visit to this period already fetched and parsed
    // the static payload, so re-render from the memoized copy instead of
    // hitting the network again. Only fully-loaded entries qualify — a retry
    // after a partial failure must still refetch the missing pieces.
    const cached = staticCacheRef.current[period];
    if (cached?.complete) {
      setHealth(cached.health);
      setDataFreshness(cached.dataFreshness);
      setFeedVintage(cached.feedVintage);
      setCircuity(cached.circuity);
      setFlaggedRoutes(cached.summary.flagged);
      setCircuityThreshold(cached.summary.threshold ?? 1.4);
      setPeriods(cached.summary.periods ?? null);
      setNodes(cached.nodes);
      setError(null);
      finishLoadStep('health');
      finishLoadStep('circuity');
      finishLoadStep('summary');
      finishLoadStep('nodes');
      return;
    }

    // Route rendering depends on `circuity` (the polyline layer). The transfer
    // node query is the slowest call (it rebuilds the whole connection graph),
    // so we must NOT gate `circuity` behind it — otherwise the map shows bare
    // tiles for ~25s until that query returns. (The backend now disk-caches
    // both artifacts, so these are fast after the first ever run.)
    // Health is settled on its own (not lumped into the Promise.all): it is
    // the fastest call and feeds the header, so reporting it late would leave
    // the progress bar pinned at 0% for the ~20s `circuity` takes on a cold
    // cache — the bar should move as each request actually settles.
    try {
      const healthPromise = api
        .health()
        .then((h) => {
          const text = `Network loaded · ${h.feed.routes} routes · ${h.feed.stops} stops`;
          if (seq === loadSeqRef.current) {
            setHealth(text);
            setDataFreshness(h.data_freshness ?? null);
            setFeedVintage(h.feed.vintage ?? null);
            setError(null);
            finishLoadStep('health');
          }
          return text;
        })
        .catch((e) => {
          if (seq === loadSeqRef.current) {
            setError(e instanceof Error ? e.message : String(e));
            finishLoadStep('health');
          }
          return 'Network loaded';
        });
      const [c, s, entryHealth] = await Promise.all([
        api.circuity({ period }),
        api.circuitySummary({ period }),
        healthPromise,
      ]);
      const entry: StaticCacheEntry = {
        health: entryHealth,
        dataFreshness: null,
        feedVintage,
        circuity: c,
        summary: s,
        nodes: [],
        complete: false,
      };
      staticCacheRef.current[period] = entry;
      if (seq !== loadSeqRef.current) return; // a newer load owns the state
      setCircuity(c);
      setFlaggedRoutes(s.flagged);
      setCircuityThreshold(s.threshold ?? 1.4);
      setPeriods(s.periods ?? null);
      setError(null);
    } catch (e) {
      if (seq !== loadSeqRef.current) return;
      setError(e instanceof Error ? e.message : String(e));
    }
    finishLoadStep('circuity');
    finishLoadStep('summary');
    // Transfer nodes load independently so a slow query never blocks routes.
    try {
      const ns = await api.transferNodes({ period, max_nodes: 120 });
      // Cache regardless of staleness (the data is still valid for this
      // period), but only apply to state if this load is still current.
      const entry = staticCacheRef.current[period];
      if (entry) {
        entry.nodes = ns;
        entry.complete = true;
      }
      if (seq !== loadSeqRef.current) return;
      setNodes(ns);
    } catch (e) {
      if (seq !== loadSeqRef.current) return;
      setError(e instanceof Error ? e.message : String(e));
    }
    finishLoadStep('nodes');
  }, [period, finishLoadStep, viewRef]);

  useEffect(() => {
    loadStatic();
  }, [loadStatic]);

  return {
    health,
    dataFreshness,
    feedVintage,
    circuity,
    flaggedRoutes,
    circuityThreshold,
    nodes,
    setNodes,
    periods,
    error,
    setError,
    loadProgress,
    finishLoadStep,
    onHomeLoaded,
    loadStatic,
  };
}
