import { Clock, TriangleAlert } from 'lucide-react';
import { isStale, vintageLabel } from '../lib/useDataVintages';
import type { DataSourceVintage } from '../types';

interface Props {
  vintage: DataSourceVintage | undefined;
  /** What the number measures, e.g. "collected departures". */
  label?: string;
  className?: string;
}

/**
 * Inline data-vintage stamp next to a headline number: "· 12 min old".
 * Turns into a warning chip when the output lags its raw input by >30 min
 * (the silent-analysis-failure signature) or when the file is missing.
 */
export default function DataVintageBadge({ vintage, label, className = '' }: Props) {
  if (!vintage) return null;
  const text = vintageLabel(vintage);
  if (!text) return null;
  const stale = isStale(vintage);
  const missing = !vintage.exists;
  const title = missing
    ? `${vintage.source}: ${vintage.file} not found — numbers from this source are hidden or degraded`
    : `${vintage.source}: ${vintage.file}, last written ${vintage.mtime ?? 'unknown'}${
        vintage.feeds_from ? `, computed from ${vintage.feeds_from}` : ''
      }${stale ? ` — its input has since moved ${vintage.input_lag_minutes} min ahead` : ''}`;
  return (
    <span
      className={`inline-flex items-center gap-1 text-[10px] ${
        stale || missing ? 'text-bottleneck' : 'text-text-muted'
      } ${className}`}
      title={title}
    >
      {stale || missing ? (
        <TriangleAlert className="h-3 w-3" aria-hidden />
      ) : (
        <Clock className="h-3 w-3" aria-hidden />
      )}
      {label && <span>{label}</span>}
      <span>{text}</span>
    </span>
  );
}
