import { Bus, HelpCircle, Menu, X } from 'lucide-react';
import { useState } from 'react';
import { useIsMobile } from '../../lib/useIsMobile';
import { DAY_LABELS, PERIOD_HIDDEN_VIEWS, SERVICE_DAY_VIEWS } from '../../lib/viewConfig';
import type { ServiceDay } from '../../lib/persist';
import type { View } from '../../lib/viewConfig';
import type { TimePeriod } from '../../types';

const FALLBACK_PERIODS: [string, { label: string }][] = [
  ['all_day', { label: 'All Day' }],
  ['am_rush', { label: 'AM Rush' }],
  ['midday', { label: 'Midday' }],
  ['pm_rush', { label: 'PM Rush' }],
  ['late_night', { label: 'Late Night (midnight–2am)' }],
];

/** feedVintage: the live feed's validity window (feed_info.txt), rendered as
 * a chip so a user can always tell which schedule era they're looking at —
 * critical once archived vintages (e.g. 2017) are loaded for comparison. */
export interface AppHeaderProps {
  view: View;
  health: string | null;
  feedVintage?: { start_date: string | null; end_date: string | null; version: string | null } | null;
  dataFreshness: string | null;
  serviceDay: ServiceDay;
  setServiceDay: (d: ServiceDay) => void;
  period: string;
  setPeriod: (p: string) => void;
  periods: Record<string, TimePeriod> | null;
  onShowHelp: () => void;
}

/** Top bar: branding + feed health, plus the service-day and time-of-day
 * pickers (only on the views where they apply). */
export default function AppHeader({
  view,
  health,
  feedVintage,
  dataFreshness,
  serviceDay,
  setServiceDay,
  period,
  setPeriod,
  periods,
  onShowHelp,
}: AppHeaderProps) {
  const isMobile = useIsMobile();
  const [navOpen, setNavOpen] = useState(false);
  return (
    <header className="relative border-b border-border bg-card">
      <div className="h-0.5 w-full bg-gradient-to-r from-optimized via-accent to-bottleneck" />
      <div className="flex items-center gap-3 px-3 py-2.5 sm:px-4">
        {isMobile && (
          <button
            onClick={() => {
              setNavOpen((v) => !v);
              window.dispatchEvent(new CustomEvent('miway:toggle-nav'));
            }}
            aria-label={navOpen ? 'Close navigation' : 'Open navigation'}
            className="shrink-0 rounded-lg border border-border p-1.5 text-text-secondary transition-colors hover:bg-card-hover"
          >
            {navOpen ? <X className="h-5 w-5" /> : <Menu className="h-5 w-5" />}
          </button>
        )}
        <div className="flex min-w-0 items-center gap-2.5">
          <div className="rounded-lg bg-gradient-to-br from-optimized/25 to-accent/20 p-1.5 shadow-[0_0_12px_rgba(0,230,118,0.15)]">
            <Bus className="h-5 w-5 text-optimized" />
          </div>
          <div>
            <h1 className="truncate text-sm font-bold leading-tight">MiWay Transit Optimizer</h1>
            <p className="hidden items-center gap-1.5 text-[11px] leading-tight text-text-muted sm:flex">
              <span>{health ?? '\u00A0'}</span>
            </p>
            {feedVintage?.start_date && (
              <p className="flex items-center gap-1 text-[10px] leading-tight text-text-muted">
                {feedVintage.start_date.slice(0, 4) !== new Date().getFullYear().toString() && (
                  <span
                    title={`Validity window of the loaded GTFS feed (feed_info.txt): ${feedVintage.start_date} → ${feedVintage.end_date ?? 'n/a'}. This is NOT this year's timetable — see docs/sources/gtfs_archive.`}
                    className="rounded bg-accent/15 px-1 py-px text-[9px] font-bold uppercase tracking-wide text-accent"
                  >
                    archived {feedVintage.start_date.slice(0, 4)} feed
                  </span>
                )}
              </p>
            )}
            {dataFreshness && (
              <p className="text-[10px] leading-tight text-text-muted">
                Data as of {new Date(dataFreshness).toLocaleString('en-CA', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })}
              </p>
            )}
          </div>
        </div>
        <div className="ml-auto flex flex-wrap items-center justify-end gap-2 sm:gap-3">
          {SERVICE_DAY_VIEWS.includes(view) && (
            <div
              role="group"
              aria-label="Service day"
              className="flex items-center gap-1 rounded-lg border border-border bg-card-hover p-0.5 text-xs"
            >
              {(['weekday', 'saturday', 'sunday'] as ServiceDay[]).map((d) => (
                <button
                  key={d}
                  onClick={() => setServiceDay(d)}
                  title={`${DAY_LABELS[d]} schedule`}
                  className={`rounded-md px-2 py-1 text-[11px] transition-all sm:px-2.5 sm:text-xs ${
                    serviceDay === d
                      ? 'bg-accent font-semibold text-bg shadow-[0_0_10px_rgba(79,195,247,0.35)]'
                      : 'text-text-secondary hover:bg-border'
                  }`}
                >
                  {DAY_LABELS[d]}
                </button>
              ))}
            </div>
          )}
          {!PERIOD_HIDDEN_VIEWS.includes(view) && (
            <div className="flex items-center gap-3">
              {SERVICE_DAY_VIEWS.includes(view) && (
                <span className="h-5 w-px bg-border" aria-hidden="true" />
              )}
              <div className="flex items-center gap-1 rounded-lg border border-border bg-card-hover p-0.5 text-xs">
                {(periods
                  ? Object.entries(periods)
                  : FALLBACK_PERIODS
                ).map(([key, p]) => (
                  <button
                    key={key}
                    onClick={() => setPeriod(key)}
                    title={`${p.label}`}
                    className={`rounded-md px-2 py-1 text-[11px] transition-all sm:px-2.5 sm:text-xs ${
                      period === key
                        ? 'bg-optimized font-semibold text-bg shadow-[0_0_10px_rgba(0,230,118,0.35)]'
                        : 'text-text-secondary hover:bg-border'
                    }`}
                  >
                    {p.label}
                  </button>
                ))}
              </div>
            </div>
          )}
          <button
            onClick={onShowHelp}
            className="inline-flex items-center gap-1.5 rounded-lg border border-border px-2.5 py-1.5 text-xs font-semibold text-text-secondary transition-colors hover:bg-card-hover"
            title="Show the getting-started guide again"
          >
            <HelpCircle className="h-4 w-4" />
            Help
          </button>
        </div>
      </div>
    </header>
  );
}
